-- Plays a random uwu when the player lands a critical hit or heal, and an
-- angry uwu / ara ara when the player gets crit or loses a big chunk of health
-- in one hit. Sound lists come from Sounds.lua (and SoundsLocal.lua for clips
-- that stay on this machine); WoW can't list files, so they are generated by
-- tools/build_sounds.py.

local ADDON_NAME, ns = ...;

local DEFAULTS = {
	enabled = true,
	crit = true,
	-- Crit heals are opt-in.
	critHeal = false,
	-- Other players' crits slip through more often in groups.
	offInParty = false,
	offInRaid = false,
	hurt = true,
	small = true,
	critCooldown = 1.5,
	hurtCooldown = 3,
	hurtPercent = 25,
	volume = 60,
	pack = "uwu",
	bubbles = true,
	bubbleX = 40,
	bubbleY = 140,
	-- The crit count under the floating text, and the counter box on screen.
	bubbleCount = false,
	counter = false,
	counterX = 300,
	counterY = -120,
	-- Cheers at crit count milestones and a sound when the player dies.
	milestones = true,
	death = true,
	-- Hawk tuah when someone nearby uses /spit.
	spit = true,
};

-- PlaySoundFile has no volume argument, so tools/build_sounds.py renders every
-- clip once per level and the sound lists hold a %d for the level.
local VOLUME_STEP = 20;

-- Small uwus fill the gaps between full ones but must not stack into noise
-- when an AoE crits ten targets in the same frame.
local SMALL_GAP = 0.2;
local CHANNEL = "Master";

-- Sound packs, in the order of the options dropdown. Only one plays at a
-- time (db.pack). Sound lists built before packs existed carry no pack name
-- and belong to the first one.
local PACKS = {
	{ id = "uwu", label = "UwU" },
	{ id = "hitmarker", label = "Hitmarker" },
	{ id = "mlg", label = "MLG" },
};
local DEFAULT_PACK = PACKS[1].id;

-- Clips that ship switched off (players found them odd); they stay on the
-- Sounds page to turn back on. Paths as in Sounds.lua; small uwus are cut from
-- the crit clips, so both go.
local function ClipPath(pool, name)
	return "Interface\\AddOns\\ForeverUwU\\sounds\\%d\\" .. pool .. "\\" .. name .. ".ogg";
end
local DEFAULT_MUTED = {};
for _, name in ipairs({ "uwu-2", "uwu-3" }) do
	tinsert(DEFAULT_MUTED, ClipPath("crit", name));
	tinsert(DEFAULT_MUTED, ClipPath("small", name));
end

local db;
local lastCrit, lastSmall, lastHurt = 0, 0, 0;
local sessionCrits = 0;
-- The biggest crit seen this session; only known when the game shows the
-- amount (in combat it can be a secret value).
local sessionBest;

local function HasSounds(pack)
	for _, list in ipairs(ns.soundLists or {}) do
		if (list.pack or DEFAULT_PACK) == pack and (#(list.crit or {}) > 0 or #(list.hurt or {}) > 0) then
			return true;
		end
	end
	return false;
end

-- Shuffle bag per pool: every clip plays once before any clip repeats,
-- and the last clip of a round never opens the next one. Clips switched off
-- on the Sounds page (db.muted, keyed by path) stay out of the bag.
local bags = {};

local function Pool(kind)
	local pool = {};
	for _, list in ipairs(ns.soundLists or {}) do
		if (list.pack or DEFAULT_PACK) == db.pack then
			for _, path in ipairs(list[kind] or {}) do
				if not db.muted[path] then
					pool[#pool + 1] = path;
				end
			end
		end
	end
	return pool;
end

local function NextSound(kind)
	local bag = bags[kind];
	if not bag or bag.pos > #bag then
		local pool = Pool(kind);
		if #pool == 0 then
			return nil;
		end
		for i = #pool, 2, -1 do
			local j = math.random(i);
			pool[i], pool[j] = pool[j], pool[i];
		end
		local previous = bag and bag[#bag];
		if #pool > 1 and pool[1] == previous then
			pool[1], pool[#pool] = pool[#pool], pool[1];
		end
		pool.pos = 1;
		bags[kind] = pool;
		bag = pool;
	end
	local path = bag[bag.pos];
	bag.pos = bag.pos + 1;
	return path;
end

-- count: the crit count to show under the floating text, if any; text and
-- scale override the clip's caption and the size of the floating text.
local function PlayPath(kind, path, pack, count, text, scale)
	if db.bubbles then
		ns.ShowBubble(kind, db.bubbleX, db.bubbleY, pack or db.pack, db.bubbleCount and count or nil, path, text, scale);
	end
	if path then
		PlaySoundFile(path:format(db.volume), CHANNEL);
		return true;
	end
	return false;
end

local function Play(kind, count)
	return PlayPath(kind, NextSound(kind), nil, count);
end

-- The clip of a pool in the chosen pack with this file name (without .ogg),
-- unless it is switched off on the Sounds page.
local function FindClip(kind, name)
	for _, path in ipairs(Pool(kind)) do
		if path:match("([^\\]+)%.ogg$") == name then
			return path;
		end
	end
end

-- The first of these clips that is there and switched on.
local function FirstClip(kind, names)
	for _, name in ipairs(names or {}) do
		local path = FindClip(kind, name);
		if path then
			return path;
		end
	end
end

-- Crit counts are kept per character in the account-wide saved variable.
local function CharacterKey()
	return (UnitName("player") or "?") .. "-" .. (GetRealmName() or "?");
end

local function CountsChanged()
	if ns.UpdateCounter then
		ns.UpdateCounter();
	end
	if ns.RefreshCritCount then
		ns.RefreshCritCount();
	end
end

-- Every crit taken as the player's own counts, also while its sound is off,
-- on cooldown or silenced in a group. amount is the damage when the game
-- shows it. Returns the character's new total.
local function CountCrit(amount)
	local key = CharacterKey();
	local total = (db.critCounts[key] or 0) + 1;
	db.critCounts[key] = total;
	sessionCrits = sessionCrits + 1;
	if amount and amount > 0 then
		sessionBest = math.max(sessionBest or 0, amount);
		db.bestCrits[key] = math.max(db.bestCrits[key] or 0, amount);
	end
	CountsChanged();
	return total;
end

-- Silent in a party or raid when the options say so. The test buttons and
-- /uwu crit|small|hurt still play.
local function Silenced()
	if IsInRaid() then
		return db.offInRaid;
	end
	return IsInGroup() and db.offInParty;
end

-- Crit count milestones get a cheer of their own: a fitting clip and a big
-- "1,000 CRITS!" instead of the usual crit sound.
local MILESTONES = { [100] = true, [500] = true, [1000] = true, [2500] = true, [5000] = true };
local MILESTONE_STEP = 10000;
local MILESTONE_CLIPS = {
	uwu = { "nico-nico-nii-T4iC52d-fVY_01", "kawaiii-vvDVZA_Ui24_06" },
	mlg = { "air-horns", "air-horn" },
};
local BIG = 1.4;

local function IsMilestone(count)
	return MILESTONES[count] or count % MILESTONE_STEP == 0;
end

local function PlayMilestone(count)
	local path = FirstClip("crit", MILESTONE_CLIPS[db.pack]) or NextSound("crit");
	return PlayPath("crit", path, nil, nil, ns.FormatCount(count) .. " CRITS!", BIG);
end

local function OnOwnCrit(amount)
	local count = CountCrit(amount);
	if not db.crit or Silenced() then
		return;
	end
	local now = GetTime();
	if db.milestones and IsMilestone(count) then
		lastCrit = now;
		lastSmall = now;
		PlayMilestone(count);
		return;
	end
	if now - lastCrit >= db.critCooldown then
		lastCrit = now;
		lastSmall = now;
		Play("crit", count);
	elseif db.small and now - lastSmall >= SMALL_GAP then
		lastSmall = now;
		Play("small", count);
	end
end

local function OnHurt()
	if not db.hurt or Silenced() then
		return;
	end
	local now = GetTime();
	if now - lastHurt >= db.hurtCooldown then
		lastHurt = now;
		-- Keeps a crit uwu from talking over the hurt sound right away.
		lastCrit = now;
		Play("hurt");
	end
end

-- The player died: a fitting clip of the hurt pool, after the hurt sound of
-- the killing hit had a moment.
local DEATH_CLIPS = {
	uwu = { "thats-hurt-senpai", "polka-itai-306", "anime-girl-scream-17667" },
	mlg = { "wasted", "mission-failed", "you-have-been-slain", "game-over" },
};
local DEATH_DELAY = 0.8;

-- test: from /uwu death, plays whatever the options say.
local function OnDeath(test)
	if not test and (not db.death or Silenced()) then
		return;
	end
	-- A random one of those that are there, so dying doesn't always sound the same.
	local found = {};
	for _, name in ipairs(DEATH_CLIPS[db.pack] or {}) do
		found[#found + 1] = FindClip("hurt", name);
	end
	local path = found[1] and found[math.random(#found)] or NextSound("hurt");
	local function Fire()
		lastHurt = GetTime();
		lastCrit = lastHurt;
		PlayPath("hurt", path);
	end
	local wait = lastHurt + DEATH_DELAY - GetTime();
	if wait > 0 then
		C_Timer.After(wait, Fire);
	else
		Fire();
	end
end

-- The combat log is off limits to addons on this client (registering
-- COMBAT_LOG_EVENT_UNFILTERED is a forbidden action), so this uses UNIT_COMBAT,
-- the event behind the hit numbers on the unit frames, plus COMBAT_TEXT_UPDATE,
-- which names crits on the player as *_CRIT. Neither has a source; see
-- WasMine below for how the player's own crits are told apart.
--
-- A killing blow comes without the CRITICAL flag even when it crit. Mobs often
-- die after a few hits, so most crits are killing blows. For those, a hit
-- clearly above the biggest recent plain hit of its damage school counts as a
-- crit. Comparing with the biggest (not the typical) hit keeps a strong ability
-- from passing as a crit auto attack; a crit auto attack that kills is missed
-- instead. Crits do double damage, spells 1.5x. Kept across fights.
local HISTORY = 15;
local MIN_HISTORY = 3;
local CRIT_FACTOR = 1.3;
local history = {};

local function Remember(school, amount)
	local list = history[school];
	if not list then
		list = {};
		history[school] = list;
	end
	list[#list + 1] = amount;
	if #list > HISTORY then
		table.remove(list, 1);
	end
end

local function LooksLikeCrit(school, amount)
	local list = history[school];
	if not list or #list < MIN_HISTORY then
		return false;
	end
	local biggest = math.max(unpack(list));
	return biggest > 0 and amount >= biggest * CRIT_FACTOR;
end

local debugMode = false;

local function Debug(...)
	if debugMode then
		print("|cffff80c0UwU|r", ...);
	end
end

-- Hawk tuah when someone uses /spit. The emote comes as CHAT_MSG_TEXT_EMOTE
-- with the text in the client's language and no emote token, so the verb is
-- matched. Custom emotes (/e spits) come as CHAT_MSG_EMOTE and don't count.
local SPIT_WORDS = { "%f[%a]spit", "%f[%a]spuckt", "%f[%a]crach", "%f[%a]escup", "%f[%a]sput" };
local SPIT_GAP = 1;
local lastSpit = 0;

-- Addons can't play a sound at a spot in the world, so the clip is rendered
-- in stereo at five spots from left to right (tools/build_sounds.py) and the
-- one on the spitter's side plays.
local SPIT_PANS = { "l2", "l1", "c", "r1", "r2" };

local function Usable(...)
	if not issecretvalue then
		return true;
	end
	for i = 1, select("#", ...) do
		if issecretvalue((select(i, ...))) then
			return false;
		end
	end
	return true;
end

-- The unit of the spitter, found by GUID or else by name.
local function IsSpitter(unit, guid, name)
	if not UnitExists(unit) then
		return false;
	end
	local unitGuid = UnitGUID(unit);
	if guid and guid ~= "" and Usable(unitGuid) then
		return unitGuid == guid;
	end
	local unitName, realm = UnitName(unit);
	if not Usable(unitName, realm) then
		return false;
	end
	-- Chat may name a sender of the own realm as "Name-Realm" too, while
	-- UnitName gives no realm for them.
	return unitName == name or (realm and realm ~= "" and unitName .. "-" .. realm == name)
		or ((not realm or realm == "") and unitName == strmatch(name, "^([^-]+)-"));
end

-- -1 far left .. 1 far right, or nil when unknown.
local function SideOnScreen(guid, name)
	if not (C_NamePlate and C_NamePlate.GetNamePlates) then
		return nil;
	end
	-- Friendly players have a nameplate only while friendly nameplates are on,
	-- and only while they are in view; the plate shows where they stand on screen.
	-- Every shown plate, whatever its nameplateN number; Blizzard's nameplate
	-- code keeps the unit on the plate (unitToken).
	for _, plate in ipairs(C_NamePlate.GetNamePlates() or {}) do
		local unit = plate.unitToken or plate.namePlateUnitToken;
		if type(unit) == "string" and IsSpitter(unit, guid, name) then
			local x = plate:GetCenter();
			if not x or not Usable(x) then
				return nil;
			end
			local mid = UIParent:GetWidth() * UIParent:GetEffectiveScale() / 2;
			return math.max(-1, math.min(1, (x * plate:GetEffectiveScale() - mid) / mid));
		end
	end
end

-- Group members outside instances: where they stand next to the character,
-- seen from the way the character faces (not the camera).
local function SideInGroup(guid, name)
	if not (UnitPosition and GetPlayerFacing) then
		return nil;
	end
	local prefix, count = "party", 4;
	if IsInRaid() then
		prefix, count = "raid", 40;
	end
	for i = 1, count do
		local unit = prefix .. i;
		if IsSpitter(unit, guid, name) then
			-- UnitPosition gives the north coordinate first, then the west one.
			local north, west = UnitPosition(unit);
			local myNorth, myWest = UnitPosition("player");
			local facing = GetPlayerFacing();
			if not (north and myNorth and facing) or not Usable(north, west, myNorth, myWest, facing) then
				return nil;
			end
			local dn, dw = north - myNorth, west - myWest;
			local distance = math.sqrt(dn * dn + dw * dw);
			if distance < 0.5 then
				return 0;
			end
			-- Facing is counted from north towards west; right of it is
			-- (sin, -cos) in north / west terms.
			return (dn * math.sin(facing) - dw * math.cos(facing)) / distance;
		end
	end
end

local function SpitPan(side)
	if not side then
		return "c";
	end
	local spot = math.floor((side + 1) / 2 * #SPIT_PANS) + 1;
	return SPIT_PANS[math.max(1, math.min(#SPIT_PANS, spot))];
end

-- side: -1 far left .. 1 far right, nil for the middle.
local function PlaySpit(side)
	local list = ns.spitSounds;
	if not list or #list == 0 then
		return false;
	end
	PlaySoundFile(list[math.random(#list)]:format(db.volume, SpitPan(side)), CHANNEL);
	return true;
end

local function OnTextEmote(text, name, guid)
	-- The event is secret in chat messaging lockdown (dungeons, raids, boss
	-- fights, PvP matches; not plain combat). Without the text there is
	-- nothing to match; without the sender the clip plays centered.
	local senderKnown = Usable(name, guid);
	Debug("emote", Usable(text) and tostring(text) or "(secret text)",
		senderKnown and tostring(name) or "(secret sender)");
	if not db.spit or not Usable(text) or type(text) ~= "string" then
		return;
	end
	if not senderKnown then
		name, guid = nil, nil;
	end
	local lower = strlower(text);
	local found = false;
	for _, word in ipairs(SPIT_WORDS) do
		if strfind(lower, word) then
			found = true;
			break;
		end
	end
	local now = GetTime();
	if not found or now - lastSpit < SPIT_GAP then
		return;
	end
	lastSpit = now;
	local side;
	if name and guid ~= UnitGUID("player") and name ~= UnitName("player") then
		side = SideOnScreen(guid, name) or SideInGroup(guid, name);
	end
	Debug("spit", name, side and ("%.2f"):format(side) or "middle");
	PlaySpit(side);
end

-- UNIT_COMBAT has no source, so a crit counts as the player's own only when
-- it lines up with something the player did: a melee swing or a spell, auto
-- shot or channel that may still be on its way. PLAYER_SWING fires when the
-- swing starts, the hit shows up about half a second later (server round
-- trip), and auto attacks only ever hit the target, so swings only vouch for
-- crits on the target. Crits of other players outside such a window are
-- dropped; one landing inside it still slips through. Periodic ticks (DoTs,
-- HoTs) and pet hits come without an action of the player and are missed.
local SWING_SLACK = 0.15;
local SWING_WINDOW = 1;
local CAST_WINDOW = 1.5;
local lastSwing, lastCast = -100, -100;
local channeling = false;

local function WasMine(time, onTarget)
	return channeling
		or (time - lastCast >= -SWING_SLACK and time - lastCast <= CAST_WINDOW)
		or (onTarget and time - lastSwing >= -SWING_SLACK and time - lastSwing <= SWING_WINDOW);
end

-- amount: the damage of the crit, when known (not for heals).
local function OnCritIfMine(time, onTarget, amount)
	time = time or GetTime();
	if WasMine(time, onTarget) then
		OnOwnCrit(amount);
		return;
	end
	-- The cast event may arrive a moment after the hit it belongs to.
	C_Timer.After(SWING_SLACK, function()
		if WasMine(time, onTarget) then
			OnOwnCrit(amount);
		else
			Debug(("crit ignored, not mine (%s, swing %+.2f s, cast %+.2f s)"):format(
				onTarget and "target" or "not target", lastSwing - time, lastCast - time));
		end
	end);
end

-- Enum.PlayerSwingType.Ranged; a missing Enum table would be a hidden Lua error
-- that silently drops every melee crit.
local RANGED_SWING = 2;

local function OnSwing(swingType)
	Debug("swing", swingType);
	if swingType == RANGED_SWING then
		-- The shot still has to fly.
		lastCast = GetTime();
	else
		lastSwing = GetTime();
	end
end

-- Only crits on the player. Crit heals on the player come as UNIT_COMBAT
-- too; counting HEAL_CRIT here as well would count every one of them twice.
local CRIT_TEXT = {
	DAMAGE_CRIT = true,
	SPELL_DAMAGE_CRIT = true,
};

local function OnCombatText(textType)
	if CRIT_TEXT[textType] then
		Debug("text", textType);
		OnHurt();
	end
end

-- Whether the player targets themselves. UnitIsUnit can be secret on
-- restricted maps; then it is taken as no.
local function TargetIsPlayer()
	local same = UnitIsUnit("target", "player");
	if issecretvalue and issecretvalue(same) then
		return false;
	end
	return same and true or false;
end

-- The last plain hit on the target, until it is known whether it killed.
local KILL_WINDOW = 0.3;
local pendingHit;

local function OnKillingBlow(how)
	local hit = pendingHit;
	pendingHit = nil;
	if not hit then
		return;
	end
	local crit = LooksLikeCrit(hit.school, hit.amount);
	Debug("kill", hit.amount, "school " .. tostring(hit.school), how, crit and "CRIT" or "");
	if crit then
		OnCritIfMine(hit.time, true, hit.amount);
	end
end

-- Mobs other than the target (Swipe, Cleave, multi-dotting) are only seen
-- through their nameplates, so only while enemy nameplates are shown. The
-- target also has a nameplate and reports every hit twice; the copy arrives in
-- the same frame with the same values. UnitIsUnit can't tell them apart, its
-- result may be secret in combat. So a crit waits for the end of the frame,
-- and a copy from the target unit marks it as a crit on the target.
local pendingCrit;

local function QueueCrit(onTarget, event, flags, amount)
	local key = GetTime() .. event .. flags .. tostring(amount);
	if pendingCrit and pendingCrit.key == key then
		pendingCrit.onTarget = pendingCrit.onTarget or onTarget;
		return;
	end
	local crit = { key = key, onTarget = onTarget, time = GetTime(),
		amount = event == "WOUND" and amount or nil };
	pendingCrit = crit;
	C_Timer.After(0, function()
		if pendingCrit == crit then
			pendingCrit = nil;
		end
		OnCritIfMine(crit.time, crit.onTarget, crit.amount);
	end);
end

local function OnNamePlateCombat(unit, event, flags, amount, school)
	-- Only crits; the killing blow guess stays with the target. Hits on
	-- friendly nameplates and heals are other people's business.
	if event ~= "WOUND" or (flags ~= "CRITICAL" and flags ~= "CRUSHING") then
		return;
	end
	-- Mobs tagged by players outside the group: see OnUnitCombat.
	if not UnitCanAttack("player", unit) or UnitIsTapDenied(unit) then
		return;
	end
	Debug(unit, event, flags, amount, "school " .. tostring(school), "CRIT");
	QueueCrit(false, event, flags, amount);
end

local function OnUnitCombat(unit, event, flags, amount, school)
	-- The amount can be a secret value in combat; comparing it is a Lua error.
	-- Then it is unknown: only the crit flag counts, no big hit or kill guess.
	if issecretvalue and issecretvalue(amount) then
		amount = nil;
	end
	if strfind(unit, "^nameplate") then
		OnNamePlateCombat(unit, event, flags, amount, school);
		return;
	elseif unit ~= "player" and unit ~= "target" then
		return;
	elseif unit == "target" and TargetIsPlayer() then
		-- Every hit on a self-targeted player also comes as "player", which
		-- handles it; the "target" copy would count a mob's crit as the
		-- player's own and a crit heal twice.
		return;
	end
	-- A mob tagged by someone outside the group is their fight; their crits on
	-- it would otherwise pass whenever they line up with a cast of the player.
	if event == "WOUND" and unit == "target" and UnitIsTapDenied(unit) then
		return;
	end
	local critical = flags == "CRITICAL" or flags == "CRUSHING";
	if unit == "player" then
		Debug(unit, event, flags, amount, critical and "CRIT" or "");
		if event == "WOUND" then
			local maxHealth = UnitHealthMax("player");
			if critical or (amount and maxHealth > 0 and amount >= maxHealth * db.hurtPercent / 100) then
				OnHurt();
			end
		elseif event == "HEAL" and critical and db.critHeal then
			OnCritIfMine();
		end
		return;
	end

	if event ~= "WOUND" and (event ~= "HEAL" or not db.critHeal) then
		return;
	end
	if critical then
		Debug(unit, event, flags, amount, "CRIT");
		QueueCrit(true, event, flags, amount);
		return;
	end
	if event ~= "WOUND" or not amount or amount <= 0 then
		return;
	end
	-- The target's health is a secret value in combat, so a killing blow shows
	-- only through UnitIsDead (which may flip a moment after the hit), the
	-- target vanishing (the client clears it when the mob dies) or the XP
	-- message that follows a kill. Until one of them says so, the hit waits.
	-- A hit that is followed by another one did not kill.
	if pendingHit then
		Remember(pendingHit.school, pendingHit.amount);
	end
	local hit = { school = school, amount = amount, time = GetTime() };
	pendingHit = hit;
	if UnitIsDead(unit) then
		OnKillingBlow("dead now");
		return;
	end
	C_Timer.After(KILL_WINDOW, function()
		if pendingHit ~= hit then
			return;
		end
		if not UnitExists(unit) then
			OnKillingBlow("target gone");
		elseif UnitIsDead(unit) then
			OnKillingBlow("dead later");
		else
			pendingHit = nil;
			Debug(unit, event, amount, "school " .. tostring(school), "alive");
			Remember(school, amount);
		end
	end);
end

local function UpdateEvents(frame)
	if db.enabled then
		-- RegisterUnitEvent takes at most two units; nameplates come and go.
		frame:RegisterEvent("UNIT_COMBAT");
		frame:RegisterEvent("COMBAT_TEXT_UPDATE");
		frame:RegisterEvent("CHAT_MSG_COMBAT_XP_GAIN");
		frame:RegisterEvent("PLAYER_SWING");
		frame:RegisterEvent("PLAYER_DEAD");
		frame:RegisterEvent("CHAT_MSG_TEXT_EMOTE");
		frame:RegisterUnitEvent("UNIT_SPELLCAST_SUCCEEDED", "player");
		frame:RegisterUnitEvent("UNIT_SPELLCAST_CHANNEL_START", "player");
		frame:RegisterUnitEvent("UNIT_SPELLCAST_CHANNEL_STOP", "player");
	else
		frame:UnregisterEvent("UNIT_COMBAT");
		frame:UnregisterEvent("COMBAT_TEXT_UPDATE");
		frame:UnregisterEvent("CHAT_MSG_COMBAT_XP_GAIN");
		frame:UnregisterEvent("PLAYER_SWING");
		frame:UnregisterEvent("PLAYER_DEAD");
		frame:UnregisterEvent("CHAT_MSG_TEXT_EMOTE");
		frame:UnregisterEvent("UNIT_SPELLCAST_SUCCEEDED");
		frame:UnregisterEvent("UNIT_SPELLCAST_CHANNEL_START");
		frame:UnregisterEvent("UNIT_SPELLCAST_CHANNEL_STOP");
		channeling = false;
	end
end

local frame = CreateFrame("Frame");

-- What Options.lua needs.
ns.DEFAULTS = DEFAULTS;
ns.PACKS = PACKS;
ns.VOLUME_STEP = VOLUME_STEP;
ns.HasSounds = HasSounds;
ns.Play = Play;
ns.PlayPath = PlayPath;
ns.PlaySpit = PlaySpit;

function ns.UpdateEvents()
	UpdateEvents(frame);
end

function ns.SetPack(pack)
	db.pack = pack;
	-- The bags still hold clips of the old pack.
	bags = {};
end

-- Every clip of a pool in the chosen pack: { path, set }.
function ns.Clips(kind)
	local clips = {};
	for _, list in ipairs(ns.soundLists or {}) do
		if (list.pack or DEFAULT_PACK) == db.pack then
			for _, path in ipairs(list[kind] or {}) do
				clips[#clips + 1] = { path = path, set = list.set };
			end
		end
	end
	return clips;
end

-- This session's and this character's total crit count, then the biggest
-- crit of the session and of the character (nil while unknown).
function ns.CritCounts()
	local key = CharacterKey();
	return sessionCrits, db.critCounts[key] or 0, sessionBest, db.bestCrits[key];
end

function ns.ResetCrits()
	local key = CharacterKey();
	db.critCounts[key] = nil;
	db.bestCrits[key] = nil;
	sessionCrits = 0;
	sessionBest = nil;
	CountsChanged();
end

-- 4210 -> "4,210"
function ns.FormatCount(n)
	local s, k = tostring(n), 1;
	while k > 0 do
		s, k = s:gsub("^(%d+)(%d%d%d)", "%1,%2");
	end
	return s;
end

function ns.SetMuted(kind, path, muted)
	db.muted[path] = muted or nil;
	-- The current round may still hold the clip, or lack it.
	bags[kind] = nil;
end

SLASH_FOREVERUWU1 = "/uwu";
SlashCmdList.FOREVERUWU = function(msg)
	msg = strlower(strtrim(msg or ""));
	if msg == "debug" then
		debugMode = not debugMode;
		print("|cffff80c0Forever UwU|r: debug " .. (debugMode and "on" or "off"));
	elseif msg == "crit" or msg == "hurt" or msg == "small" then
		if not Play(msg) then
			print("|cffff80c0Forever UwU|r: no " .. msg .. " sounds installed, or all of them are off under /uwu sounds.");
		end
	elseif msg == "death" then
		OnDeath(true);
	elseif msg == "milestone" then
		PlayMilestone(1000);
	elseif msg == "spit" or msg == "spit left" or msg == "spit right" then
		-- /uwu spit left|right checks that the stereo spots work.
		PlaySpit(msg == "spit left" and -1 or msg == "spit right" and 1 or nil);
	elseif msg == "sounds" then
		ns.ToggleOptions("sounds");
	else
		ns.ToggleOptions();
	end
end;

frame:RegisterEvent("ADDON_LOADED");
frame:RegisterEvent("PLAYER_LOGIN");
frame:SetScript("OnEvent", function(self, event, arg1, ...)
	if event == "UNIT_COMBAT" then
		OnUnitCombat(arg1, ...);
	elseif event == "COMBAT_TEXT_UPDATE" then
		OnCombatText(arg1);
	elseif event == "CHAT_MSG_COMBAT_XP_GAIN" then
		OnKillingBlow("xp");
	elseif event == "PLAYER_SWING" then
		OnSwing(...);
	elseif event == "PLAYER_DEAD" then
		OnDeath();
	elseif event == "CHAT_MSG_TEXT_EMOTE" then
		-- text, sender, then the sender's GUID as the 12th argument.
		OnTextEmote(arg1, (...), (select(11, ...)));
	elseif event == "UNIT_SPELLCAST_SUCCEEDED" then
		lastCast = GetTime();
	elseif event == "UNIT_SPELLCAST_CHANNEL_START" then
		channeling = true;
	elseif event == "UNIT_SPELLCAST_CHANNEL_STOP" then
		-- The last tick can land after the channel ends.
		channeling = false;
		lastCast = GetTime();
	elseif event == "ADDON_LOADED" then
		if arg1 == ADDON_NAME then
			self:UnregisterEvent("ADDON_LOADED");
			ForeverUwUDB = ForeverUwUDB or {};
			db = ForeverUwUDB;
			for key, value in pairs(DEFAULTS) do
				if db[key] == nil then
					db[key] = value;
				end
			end
			-- A table can't live in DEFAULTS: the copy would share it.
			db.muted = db.muted or {};
			-- Clips that ship switched off: muted once per clip, so a player
			-- who turns one back on under /uwu sounds keeps it on.
			db.mutedDefaults = db.mutedDefaults or {};
			for _, path in ipairs(DEFAULT_MUTED) do
				if not db.mutedDefaults[path] then
					db.mutedDefaults[path] = true;
					db.muted[path] = true;
				end
			end
			db.critCounts = db.critCounts or {};
			db.bestCrits = db.bestCrits or {};
			-- Only the rendered levels exist as files.
			db.volume = math.min(100, math.max(VOLUME_STEP,
				math.floor(db.volume / VOLUME_STEP + 0.5) * VOLUME_STEP));
			-- A pack that is gone (local clips removed) would leave the addon mute.
			if not HasSounds(db.pack) then
				db.pack = DEFAULT_PACK;
			end
			ns.db = db;
			ns.RegisterOptionsStub();
		end
	elseif event == "PLAYER_LOGIN" then
		UpdateEvents(self);
		ns.UpdateCounter();
	end
end);
